								</p>
								<button
									v-for="k in karyawanTersaring"
									:key="k.name"
									type="button"
									class="flex w-full items-center gap-3 rounded-2xl border px-4 py-3 text-left transition"
									:class="
										form.employee === k.name
											? 'border-primary bg-primary/5'
											: 'border-ui-line-gray-200 active:bg-ui-surface-gray-50'
									"
									@click="pilihKaryawan(k.name)"
								>
									<span
										class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-sm font-bold"
										:class="
											form.employee === k.name
												? 'bg-primary text-ui-onPrimary'
												: 'bg-ui-surface-gray-100 text-ui-ink-gray-500'
										"
										>{{ inisial(k.employee_name) }}</span
									>
									<span class="min-w-0 flex-1">
										<span
											class="block truncate text-sm font-medium text-ui-ink-gray-900"
											>{{ k.employee_name
											}}<span v-if="k.sendiri" class="text-ui-ink-gray-400">
												(saya)</span
											></span
										>
										<span class="block truncate text-xs text-ui-ink-gray-400">{{
											k.department || k.name
										}}</span>
									</span>
									<svg
										v-if="form.employee === k.name"
										xmlns="http://www.w3.org/2000/svg"
										viewBox="0 0 24 24"
										class="h-5 w-5 shrink-0 text-primary"
										fill="none"
										stroke="currentColor"
										stroke-width="3"
										stroke-linecap="round"
										stroke-linejoin="round"
									>
										<path d="M20 6 9 17l-5-5" />
									</svg>
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { createResource, toast } from 'frappe-ui'
import { angka, tanggal } from '../data/cutiStatus'
import CutiDatePicker from '../components/CutiDatePicker.vue'
import { openAttachment } from '../composables/pdfViewer'

function inisial(nama) {
	return (nama || '?')
		.split(/\s+/)
		.slice(0, 2)
		.map((x) => x[0])
		.join('')
		.toUpperCase()
}

const props = defineProps({ name: { type: String, default: '' } })
const router = useRouter()

// Satu komponen dipakai dua mode: tanpa `name` berarti membuat baru, dengan
// `name` berarti mengubah draft yang sudah ada.
const modeUbah = computed(() => !!props.name)

const opsi = ref(null)
const blokir = ref('')
const pratinjau = ref(null)
const saving = ref(false)
const showKaryawan = ref(false)
const cariKaryawan = ref('')
const errorMsg = ref('')
const inputFile = ref(null)
const unggah = ref(false)

const form = reactive({
	employee: '',
	leave_type: '',
	jenis_kejadian: '',
	from_date: '',
	to_date: '',
	description: '',
	mc_file: '',
})

const karyawanTerpilih = computed(
	() => opsi.value?.karyawan?.find((k) => k.name === form.employee) || null
)

const karyawanTersaring = computed(() => {
	const q = cariKaryawan.value.trim().toLowerCase()
	const semua = opsi.value?.karyawan || []
	if (!q) return semua
	return semua.filter(
		(k) => k.employee_name.toLowerCase().includes(q) || k.name.toLowerCase().includes(q)
	)
})

async function pilihKaryawan(nama) {
	showKaryawan.value = false
	cariKaryawan.value = ''
	if (nama === form.employee) return
	form.employee = nama
	await gantiKaryawan()
}

const jenisTerpilih = computed(
	() => opsi.value?.leave_types?.find((x) => x.name === form.leave_type) || null
)
const butuhKejadian = computed(() => !!jenisTerpilih.value?.is_cuti_khusus)
// Cuti sakit dibuat terbuka: hanya tanggal mulai, tanggal akhirnya menyusul
// saat karyawan absen masuk lagi.
const cutiTerbuka = computed(() => !!jenisTerpilih.value?.tanpa_batas)
// Hanya cuti sakit yang punya surat dokter untuk dilampirkan. Penandanya datang
// dari Jenis Cuti, jadi HR bisa menambah jenis lain tanpa mengubah portal.
const perluMc = computed(() => !!jenisTerpilih.value?.perlu_mc)

// Melebihi plafon kejadian → tombol tetap aktif, server yang menolak dengan
// pesan pastinya. Di sini hanya diberi warna sebagai peringatan dini.
const pratinjauMelebihi = computed(() => {
	const p = pratinjau.value
	if (!p || p.tanpa_batas) return false
	if (p.plafon !== undefined) return p.hari > p.plafon
	if (p.saldo !== undefined) return p.hari > p.saldo
	return false
})

// Hari yang tidak tertutup saldo. Bukan penghalang lagi — inilah yang nanti
// dibagi Direktur jadi hutang cuti atau hari tanpa upah.
const hariKelebihan = computed(() => Number(pratinjau.value?.kelebihan || 0))

// Satu-satunya keadaan yang benar-benar menghalangi: tahap terakhirnya adalah
// persetujuan pemohon sendiri, dan tanpa akun login tidak ada yang bisa
// menjawabnya — dokumennya akan menggantung selamanya.
const kelebihanTerhalang = computed(
	() => hariKelebihan.value > 0 && pratinjau.value?.punya_akun === false
)

// "Anda" hanya benar bila mengajukan untuk diri sendiri. Atasan dan HR yang
// mengisikan atas nama orang lain harus membaca "pemohon".
const untukSaya = computed(() => karyawanTerpilih.value?.sendiri !== false)

// Batas hanya berarti setelah ada rentang yang bisa dibandingkan.
const batasTampil = computed(
	() =>
		!!pratinjau.value &&
		(pratinjau.value.tanpa_batas ||
			pratinjau.value.plafon !== undefined ||
			pratinjau.value.saldo !== undefined)
)

const bisaKirim = computed(
	() =>
		!!form.employee &&
		!!form.leave_type &&
		!!form.from_date &&
		(cutiTerbuka.value || !!form.to_date) &&
		!!form.description.trim() &&
		(!butuhKejadian.value || !!form.jenis_kejadian) &&
		!kelebihanTerhalang.value &&
		!opsi.value?.atasan_tanpa_login
)

const opsiRes = createResource({
	url: 'juragan.api.portal.cuti.get_opsi_form',
	method: 'GET',
	auto: false,
	makeParams: () => (form.employee ? { employee: form.employee } : {}),
	onSuccess: (d) => {
		opsi.value = d
		form.employee = d.employee
	},
	onError: (e) => {
		// Akun belum tertaut karyawan → tampilkan alasannya, bukan form kosong.
		blokir.value = e?.messages?.[0] || e?.message || 'Tidak bisa membuka formulir pengajuan.'
	},
})

const hitungRes = createResource({
	url: 'juragan.api.portal.cuti.hitung_hari',
	method: 'GET',
	auto: false,
	makeParams: () => {
		const p = {
			leave_type: form.leave_type,
			from_date: form.from_date,
		}
		if (form.to_date) p.to_date = form.to_date
		if (form.employee) p.employee = form.employee
		if (form.jenis_kejadian) p.jenis_kejadian = form.jenis_kejadian
		// Saat mengubah draft, riwayat dihitung sampai sebelum dokumen ini.
		if (props.name) p.name = props.name
		return p
	},
	onSuccess: (d) => {
		pratinjau.value = d
	},
	onError: () => {
		pratinjau.value = null
	},
})

const simpanRes = createResource({
	url: 'juragan.api.portal.cuti.buat_pengajuan',
	method: 'POST',
})

const ubahRes = createResource({
	url: 'juragan.api.portal.cuti.update_pengajuan',
	method: 'POST',
})

// Isi form dari draft yang sedang diubah. Dipanggil sebelum opsi diambil,
// supaya jatah & kejadian yang dimuat sudah milik karyawan yang benar.
const detailRes = createResource({
	url: 'juragan.api.portal.cuti.get_detail',
	method: 'GET',
	auto: false,
	makeParams: () => ({ name: props.name }),
	onSuccess: (d) => {
		form.employee = d.employee
		form.leave_type = d.leave_type
		form.jenis_kejadian = d.jenis_kejadian || ''
		form.from_date = d.from_date
		form.to_date = d.to_date
		form.description = d.description || ''
		form.mc_file = d.mc_file || ''
	},
})

// Ganti karyawan → jatah, kejadian, dan tujuan persetujuan ikut berubah, jadi
// pilihan yang terlanjur dibuat dikosongkan supaya tidak tertinggal milik orang
// sebelumnya.
async function gantiKaryawan() {
	form.leave_type = ''
	form.jenis_kejadian = ''
	pratinjau.value = null
	await opsiRes.fetch()
}

function pilihJenis(lt) {
	// Terkunci selama masih ada cuti jenis itu yang belum selesai. Tombolnya
	// sudah nonaktif; ini penjaga kedua kalau ada jalur lain yang memanggilnya.
	if (lt.terkunci) return
	// Berpindah ke/dari cuti sakit mengubah arti tanggal akhir — dibuang supaya
	// tidak ada sisa pilihan dari jenis sebelumnya.
	if (lt.tanpa_batas) form.to_date = ''
	// Lampiran MC hanya berlaku pada jenis yang memintanya; kalau tidak dibuang,
	// berkas itu terkirim diam-diam ke dokumen yang tidak menampilkannya.
	if (!lt.perlu_mc) form.mc_file = ''
	form.leave_type = lt.name
	if (!lt.is_cuti_khusus) form.jenis_kejadian = ''
	hitung()
}

function pilihKejadian(k) {
	if (k.terkunci) return
	form.jenis_kejadian = k.name
	hitung()
}

function namaFile(url) {
	if (!url) return ''
	const bersih = String(url).split('?')[0]
	return decodeURIComponent(bersih.substring(bersih.lastIndexOf('/') + 1)) || bersih
}

function pilihFile() {
	errorMsg.value = ''
	if (!inputFile.value) return
	inputFile.value.value = ''
	inputFile.value.click()
}

// Diunggah lebih dulu, dokumennya menyusul: pengajuan baru belum punya nama
// yang bisa dituju berkasnya. Server yang menautkan keduanya setelah tersimpan,
// supaya approver ikut bisa membuka surat privat itu.
async function unggahFile(e) {
	const file = e.target.files?.[0]
	if (!file) return
	const MAKS_MB = 3
	if (file.size > MAKS_MB * 1024 * 1024) {
		errorMsg.value = `Ukuran file maksimal ${MAKS_MB} MB.`
		return
	}
	unggah.value = true
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		form.mc_file = json.message?.file_url || ''
	} catch (err) {
		errorMsg.value = err.message || 'Gagal mengunggah lampiran.'
	} finally {
		unggah.value = false
	}
}

function hitung() {
	if (!form.leave_type || !form.from_date || (!form.to_date && !cutiTerbuka.value)) {
		pratinjau.value = null
		return
	}
	hitungRes.fetch()
}

watch(() => [form.from_date, form.to_date], hitung)

// Hanya menyimpan sebagai Draft. Pengirimannya dilakukan dari halaman detail
// lewat tombol Action → "Ajukan Cuti", supaya pemohon sempat memeriksa ulang
// isian sebelum dokumennya terkunci.
async function simpan() {
	if (!bisaKirim.value || saving.value) return
	saving.value = true
	errorMsg.value = ''
	try {
		const muatan = {
			leave_type: form.leave_type,
			from_date: form.from_date,
			ajukan: 0,
		}
		if (form.to_date) muatan.to_date = form.to_date
		if (form.employee) muatan.employee = form.employee
		if (form.jenis_kejadian) muatan.jenis_kejadian = form.jenis_kejadian
		muatan.description = form.description.trim()
		// Selalu dikirim, termasuk saat kosong: mengubah draft juga berarti
		// boleh mencabut lampiran yang sudah terlanjur dipilih.
		muatan.mc_file = perluMc.value ? form.mc_file : ''

		let nama = props.name
		if (modeUbah.value) {
			delete muatan.ajukan
			await ubahRes.submit({ ...muatan, name: props.name })
			toast.success('Perubahan tersimpan')
		} else {
			const res = await simpanRes.submit(muatan)
			nama = res.name
			toast.success('Tersimpan sebagai draft')
		}
		router.replace({ name: 'CutiDetail', params: { name: nama } })
	} catch (e) {
		errorMsg.value = e?.messages?.[0] || e?.message || 'Gagal menyimpan pengajuan.'
	} finally {
		saving.value = false
	}
}

onMounted(async () => {
	if (modeUbah.value) await detailRes.fetch()
	await opsiRes.fetch()
	hitung()
})
</script>
